  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    if not isinstance(segments, list) or not segments:
        raise ValueError('segments must be a non-empty list')
    for seg in segments:
        for key in ('name','importance','minimum','capacity'):
            if key not in seg or not isinstance(seg[key], int):
                raise ValueError(f'segment missing or invalid {key}')
    if not isinstance(budget, int):
        raise ValueError('budget must be int')
    sum_min = sum(seg['minimum'] for seg in segments)
    sum_cap = sum(seg['capacity'] for seg in segments)
    if budget < sum_min or budget > sum_cap:
        raise ValueError('budget not feasible')
    n = len(segments)
    alloc = [seg['minimum'] for seg in segments]
    remaining = budget - sum_min
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i, seg in enumerate(segments):
            if alloc[i] >= seg['capacity']:
                continue
            score = seg['importance'] / (alloc[i] + 1)
            if score > best_score:
                best_score = score
                best_idx = i
        if best_idx == -1:
            raise ValueError('cannot allocate more, but budget remains')
        alloc[best_idx] += 1
        remaining -= 1
    total = sum(alloc)
    by_name = {}
    for i, seg in enumerate(segments):
        by_name[seg['name']] = alloc[i]
    return {
        'allocations': alloc,
        'by_name': by_name,
        'total': total
    }"
}
